'use strict';
const fs=require('node:fs'),path=require('node:path'),zlib=require('node:zlib'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const repo=path.resolve(__dirname,'..'),manifest=JSON.parse(fs.readFileSync('/private/tmp/seti-funded-scan-launch-20261119.json')),rt=manifest.runtime;
const cases={before287:'teacher-r4-before-input287-20261119-v1.json.gz',before246:'teacher-r4-before-input246-20261119-v1.json.gz',before263:'teacher-r4-before-input263-20261119-v1.json.gz',after287:'teacher-r4-blind-after287-20261119-v1.json.gz',io:'teacher-r4-held-pickup-io-20261119-v1.json.gz',enceladus:'teacher-r4-held-pickup-enceladus-20261119-v1.json.gz'};
