assert(envelope);const output=path.join(repo,'reports/ai-foundation-20261119','funded-scan-launch-'+name+'-cold-20261119-'+(process.argv[3]||'v1')+'.json');assert(!fs.existsSync(output)&&!fs.existsSync(output+'.gz'),'Reuse an existing attempt');
const {createSimulationRuleComposition}=require(path.join(rt,'randomizer/training/simulation-rule-composition')),{createSeededRandom}=require(path.join(rt,'randomizer/game/random')),{buildRuleObservation}=require(path.join(rt,'randomizer/app/rule-observation')),{createAnalysisPort}=require(path.join(rt,'randomizer/game/ai/analysis-port')),{searchDecision}=require(path.join(rt,'randomizer/game/ai/decision-search')),value=require(path.join(rt,'randomizer/game/ai/state-value')),agent=require(path.join(rt,'randomizer/game/ai/search-agent'));
