 if(name==='io'){assert.equal(action?.family,'scan');assert(result.roots.some(r=>r.goal?.launch&&r.value===result.value),'the winning scan must include the funded launch purpose');}persist();console.log(JSON.stringify({case:name,status:report.status,complete:result.complete,nativeInputs:report.nativeInputs,milliseconds,action:action?.target}));if(report.status!=='passed')process.exitCode=1;
